<template>
  <div class="container no-padding">
    <div class="row full-width secondary-c-text q-pt-sm q-pb-sm">
      <div class="col-6 pl-20" v-if="is_visible">
        <f-btn appearance="tertiary" :to="routeWithAnchor">
          <Icon icon="mdi:arrow-left-circle" width="20" height="20" />
          <label
            style="
              vertical-align: middle;
              margin-left: 10px;
              font-size: 20px;
              cursor: pointer;
            "
            >{{ $t(label) }}</label
          >
        </f-btn>
      </div>
      <div class="pr-22" :class="is_visible ? 'col-6' : 'col-12'">
        <slot />
        <q-btn
          v-if="create_new_btn"
          color="primary"
          class="float-right q-ml-sm"
          icon="add"
          :to="create_new_btn"
          :label="$t('new')"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">

import { defineComponent, ref, computed } from 'vue';
import { useRoute } from 'vue-router';

export default defineComponent({
  components: {
    
  },
  setup(props) {
    const route = useRoute();
    let is_visible = true;
    if (route.meta.primary_breadcrumbs) {
      is_visible = false;
    }

    const routeWithAnchor = computed(() => {
      return props.anchor
        ? `${props.back_to_rotue}#${props.anchor}`
        : props.back_to_rotue;
    });

    return {
      route,
      is_visible,
      routeWithAnchor,
    };
  },
  props: {
    back_to_rotue: {
      type: String,
      default: '/setting',
    },
    anchor: {
      type: String,
      default: '',
    },
    create_new_btn: {
      type: String,
      default: '',
    },
    label: {
      type: String,
      default: 'layout.settings',
    },
  },
});
</script>
